def is_paired(input_string):
    """Return True if all brackets in input_string are properly paired and nested."""
    if input_string is None:
        return True

    pairs = {')': '(', ']': '[', '}': '{'}
    openings = set(pairs.values())
    stack = []

    for ch in input_string:
        if ch in openings:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()

    return not stack
